#include <iostream>
using namespace std;
int main() {
    int num = 50;
    int *ptr = &num;    // pointer initialized with the address of num
    cout << "Value of num = " << num << endl;
    cout << "Address of num = " << ptr << endl;
    cout << "Value through pointer = " << *ptr << endl;
    return 0;
}
